    out = [row[:] for row in grid]
    # Background-valued components enclosed in a different color are tiles;
    # isolated non-background pixels are noise. Remove the single-cell noise,
    # except color-zero cells embedded in the separate color-3 pattern.
    seen = set()
    for r in range(h):
        for c in range(w):
            if (r,c) in seen or grid[r][c] == bg:
                continue
            color = grid[r][c]
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
